+    // Do not echo question text or raw file payloads to logs.
+    console.error(JSON.stringify({ verdict: 'FAIL', reason: error instanceof Error ? error.message : 'Invalid input', publication_approved: false }))
+    process.exitCode = 1
+  }
+}

